/* mapics — frontend logic
 *
 * Loads data.json (generated by `npm run build`), drops each geotagged photo onto
 * a Leaflet + OpenStreetMap map. Photos are clustered into dots when zoomed out and
 * become photo thumbnails as you zoom in. Clicking a thumbnail opens the photo as a
 * polaroid with its caption.
 */

const THUMBNAIL_ZOOM = 13; // at/above this zoom, individual pins show as photo thumbnails
const DATA_URL = "data.json";

const map = L.map("map", {
  zoomControl: true,
  worldCopyJump: true,
  minZoom: 2,
});

L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
  maxZoom: 19,
  attribution:
    '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
}).addTo(map);

// Sensible default view (whole world) until data loads.
map.setView([20, 0], 2);

// ---- Polaroid modal ---------------------------------------------------------

const overlay = document.getElementById("polaroid-overlay");
const polaroidPhoto = document.getElementById("polaroid-photo");
const polaroidMessage = document.getElementById("polaroid-message");
const polaroidMeta = document.getElementById("polaroid-meta");

function formatMeta(photo) {
  const parts = [];
  if (photo.date) {
    const d = new Date(photo.date);
    if (!Number.isNaN(d.getTime())) {
      parts.push(
        d.toLocaleDateString(undefined, { year: "numeric", month: "long", day: "numeric" })
      );
    }
  }
  parts.push(`${photo.lat.toFixed(4)}, ${photo.lng.toFixed(4)}`);
  return parts.join(" · ");
}

function openPolaroid(photo) {
  polaroidPhoto.src = photo.full;
  polaroidPhoto.alt = photo.caption || photo.file;
  polaroidMessage.textContent = photo.caption || "";
  polaroidMeta.textContent = formatMeta(photo);
  overlay.classList.remove("hidden");
  // Trigger the entrance animation.
  requestAnimationFrame(() => overlay.classList.add("visible"));
}

function closePolaroid() {
  overlay.classList.remove("visible");
  overlay.addEventListener(
    "transitionend",
    () => {
      overlay.classList.add("hidden");
      polaroidPhoto.src = "";
    },
    { once: true }
  );
}

document.getElementById("polaroid-close").addEventListener("click", closePolaroid);
overlay.addEventListener("click", (e) => {
  if (e.target === overlay) closePolaroid();
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !overlay.classList.contains("hidden")) closePolaroid();
});

// ---- Markers ----------------------------------------------------------------

function makeThumbIcon(photo) {
  return L.divIcon({
    className: "photo-pin",
    html: `<div class="photo-pin-inner"><img src="${photo.thumb}" alt="" loading="lazy" /></div>`,
    iconSize: [56, 56],
    iconAnchor: [28, 62], // bottom-center tip
    popupAnchor: [0, -60],
  });
}

function makeDotIcon() {
  return L.divIcon({
    className: "photo-dot",
    html: '<span class="photo-dot-inner"></span>',
    iconSize: [16, 16],
    iconAnchor: [8, 8],
  });
}

function iconForZoom(photo, zoom) {
  return zoom >= THUMBNAIL_ZOOM ? makeThumbIcon(photo) : makeDotIcon();
}

async function init() {
  let photos = [];
  try {
    const res = await fetch(DATA_URL, { cache: "no-cache" });
    if (res.ok) photos = await res.json();
  } catch {
    /* data.json missing → empty state */
  }

  if (!Array.isArray(photos) || photos.length === 0) {
    document.getElementById("empty-state").classList.remove("hidden");
    return;
  }

  const cluster = L.markerClusterGroup({
    showCoverageOnHover: false,
    maxClusterRadius: 50,
    spiderfyOnMaxZoom: true,
    iconCreateFunction(clusterObj) {
      const count = clusterObj.getChildCount();
      return L.divIcon({
        className: "photo-cluster",
        html: `<div class="photo-cluster-inner"><span>${count}</span></div>`,
        iconSize: [44, 44],
      });
    },
  });

  const markers = [];
  for (const photo of photos) {
    const marker = L.marker([photo.lat, photo.lng], {
      icon: iconForZoom(photo, map.getZoom()),
      title: photo.caption || photo.file,
    });
    marker.photo = photo;
    marker.on("click", () => openPolaroid(photo));
    markers.push(marker);
    cluster.addLayer(marker);
  }
  map.addLayer(cluster);

  // Swap dot <-> thumbnail icons when the zoom threshold is crossed.
  let lastMode = map.getZoom() >= THUMBNAIL_ZOOM ? "thumb" : "dot";
  map.on("zoomend", () => {
    const mode = map.getZoom() >= THUMBNAIL_ZOOM ? "thumb" : "dot";
    if (mode === lastMode) return;
    lastMode = mode;
    for (const marker of markers) {
      marker.setIcon(iconForZoom(marker.photo, map.getZoom()));
    }
  });

  // Fit to all photos.
  const bounds = L.latLngBounds(photos.map((p) => [p.lat, p.lng]));
  map.fitBounds(bounds, { padding: [60, 60], maxZoom: 15 });
}

init();
